<div class="page-heading"><div><div class="eyebrow"><?= $resource->transaction?'PERGERAKAN INVENTORI':'DIREKTORI WORKSPACE' ?></div><h1><?= e($title) ?></h1><p><?= $resource->transaction?'Catat pergerakan barang. Saldo stok diperbarui otomatis.':'Kelola informasi '.strtolower(e($title)).' dalam satu tempat.' ?></p></div><?php if($canWrite): ?><a class="btn btn-primary" href="/<?= e($resource->key) ?>/create">＋ Tambah <?= $resource->key==='users'?'user':'data' ?></a><?php endif; ?></div>
<section class="panel"><div class="panel-heading"><div><h2>Daftar <?= e(strtolower($title)) ?> <span class="subtle-badge"><?= count($rows) ?> data</span></h2></div></div>
<?php if($resource->key==='barang'): ?><div class="filter-bar"><div><label for="category-filter">Kategori</label><select class="form-select table-filter" id="category-filter" data-column="3"><option value="">Semua kategori</option><?php foreach(array_unique(array_column($rows,'kategori')) as $category): ?><option><?= e($category) ?></option><?php endforeach; ?></select></div><div><label for="warehouse-filter">Gudang</label><select class="form-select table-filter" id="warehouse-filter" data-column="6"><option value="">Semua gudang</option><?php foreach($options['gudang'] as $name): ?><option><?= e($name) ?></option><?php endforeach; ?></select></div></div><?php endif; ?>
<div class="table-container"><table class="table data-table" id="resource-table"><thead><tr><th>ID</th><?php if($resource->transaction): ?><th>Nomor transaksi</th><?php endif; ?><?php foreach($resource->fields as $name=>$field): if(in_array($field['type'],['textarea']))continue; ?><th><?= e($field['label']) ?></th><?php endforeach; ?><?php if($resource->key==='barang'): ?><th>Stok</th><?php endif; ?><th data-orderable="false">Aksi</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= (int)$row['id'] ?></td><?php if($resource->transaction): ?><td class="code-cell"><?= e($row['nomor_transaksi']) ?></td><?php endif; ?><?php foreach($resource->fields as $name=>$field): if($field['type']==='textarea')continue; ?><td><?php if($name==='is_active'): ?><span class="badge-soft <?= $row[$name]?'green':'gray' ?>"><?= $row[$name]?'Aktif':'Nonaktif' ?></span><?php else: ?><?= e($field['type']==='select'?($options[$field['source']][$row[$name]]??'—'):$row[$name]) ?><?php endif; ?></td><?php endforeach; ?><?php if($resource->key==='barang'): ?><td data-order="<?= (int)$row['stok'] ?>"><span class="badge-soft <?= $row['stok']<=$row['stok_minimum']?'amber':'green' ?>"><?= (int)$row['stok'] ?><?= $row['stok']<=$row['stok_minimum']?' · Rendah':'' ?></span></td><?php endif; ?><td><div class="action-group"><a class="btn btn-sm btn-light" href="/<?= e($resource->key) ?>/<?= (int)$row['id'] ?>">Detail</a><?php if($canWrite): ?><a class="btn btn-sm btn-light" href="/<?= e($resource->key) ?>/<?= (int)$row['id'] ?>/edit">Edit</a><?php if($resource->key!=='users'): ?><form method="post" class="delete-form" action="/<?= e($resource->key) ?>/<?= (int)$row['id'] ?>/delete"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger" type="submit">Hapus</button></form><?php endif; endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></section>
